#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int h, a, b;
} Piece;

int cmp(const void *a, const void *b) {
    return ((Piece*)a)->h - ((Piece*)b)->h;
}

int main() {
    int n;
    scanf("%d", &n);
    Piece *p = malloc(n * sizeof(Piece));
    for (int i = 0; i < n; i++) {
        scanf("%d %d %d", &p[i].h, &p[i].a, &p[i].b);
    }
    qsort(p, n, sizeof(Piece), cmp);

    // We maintain multiset of available support heights
    // Using simple array for small constraints (N <= 200000 but heights up to 1e9)
    // We'll use a simple simulation with a large enough array and pointer

    int *support = malloc(2 * n * sizeof(int));
    int support_count = 0;

    for (int i = 0; i < n; i++) {
        int need_left = p[i].a;
        int need_right = p[i].b;
        int found_left = 0, found_right = 0;

        // Check if left can be placed on table
        if (need_left == 0) found_left = 1;
        else {
            for (int j = 0; j < support_count; j++) {
                if (support[j] == need_left) {
                    found_left = 1;
                    // Remove this support
                    support[j] = support[support_count-1];
                    support_count--;
                    break;
                }
            }
            if (!found_left) {
                // Check if it can be placed on a piece's center height
                for (int j = 0; j < support_count; j++) {
                    if (support[j] >= need_left) {
                        found_left = 1;
                        break;
                    }
                }
            }
        }

        // Check if right can be placed on table
        if (need_right == 0) found_right = 1;
        else {
            for (int j = 0; j < support_count; j++) {
                if (support[j] == need_right) {
                    found_right = 1;
                    support[j] = support[support_count-1];
                    support_count--;
                    break;
                }
            }
            if (!found_right) {
                for (int j = 0; j < support_count; j++) {
                    if (support[j] >= need_right) {
                        found_right = 1;
                        break;
                    }
                }
            }
        }

        if (!found_left || !found_right) {
            printf("NO\n");
            free(p);
            free(support);
            return 0;
        }

        // Add this piece's center height as new support
        support[support_count++] = p[i].h;
    }

    printf("YES\n");
    free(p);
    free(support);
    return 0;
}

