typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    ll H;
    if (scanf("%d %lld", &N, &H) != 2) return 0;

    ll *need = (ll*)malloc(sizeof(ll) * 2LL * N);
    ll *have = (ll*)malloc(sizeof(ll) * 2LL * N);
    int nc = 0, hc = 0;

    for (int i = 0; i < N; i++) {
        ll A, B;
        scanf("%lld %lld", &A, &B);

        if (A > H) need[nc++] = A - H;
        else if (A < H) have[hc++] = H - A;

        if (B > H) need[nc++] = B - H;
        else if (B < H) have[hc++] = H - B;
    }

    if (nc != hc) {
        puts("No");
        free(need);
        free(have);
        return 0;
    }

    qsort(need, nc, sizeof(ll), cmp_ll);
    qsort(have, hc, sizeof(ll), cmp_ll);

    for (int i = 0; i < nc; i++) {
        if (need[i] != have[i]) {
            puts("No");
            free(need);
            free(have);
            return 0;
        }
    }

    puts("Yes");
    free(need);
    free(have);
    return 0;
}

