public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int H = sc.nextInt();
        int[] A = new int[N];
        int[] B = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextInt();
            B[i] = sc.nextInt();
        }

        // Centers are all equal to H
        // We have N centers of height H, plus table height 0 (infinite width)
        // Left and right tabs need support height >= their height.

        // For each tab, we need a center of height >= tab height.
        // Since all centers are H, any tab with height <= H can be placed.
        // But the catch: each center can support at most one left and one right tab?
        // Actually a center can support left of one piece and right of another.
        // So we just need enough centers for left tabs and enough for right tabs.
        // Since N centers, and N left tabs, N right tabs -> we need N supports for left, N for right.
        // Table can support any number, so if H is large enough to cover all left and right, it's always possible.
        // But if some A_i > H, then we need another center of height >= A_i -> impossible since all centers = H.
        // Similarly for B_i.

        boolean possible = true;
        for (int i = 0; i < N; i++) {
            if (A[i] > H || B[i] > H) {
                possible = false;
                break;
            }
        }

        System.out.println(possible ? "YES" : "NO");
    }
}

