import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long H = fs.nextLong();

        long[] A = new long[N];
        long[] B = new long[N];

        long sumNeed = 0;   // total support needed by side parts strictly above table
        long sumCap = 0;    // total available top length from all center parts
        long maxNeed = 0;   // largest single required support
        long maxCap = 0;    // largest single available top length

        for (int i = 0; i < N; i++) {
            A[i] = fs.nextLong();
            B[i] = fs.nextLong();

            if (A[i] > H) {
                long x = A[i] - H;
                sumNeed += x;
                maxNeed = Math.max(maxNeed, x);
            }
            if (B[i] > H) {
                long x = B[i] - H;
                sumNeed += x;
                maxNeed = Math.max(maxNeed, x);
            }

            if (A[i] < H) {
                long x = H - A[i];
                sumCap += x;
                maxCap = Math.max(maxCap, x);
            }
            if (B[i] < H) {
                long x = H - B[i];
                sumCap += x;
                maxCap = Math.max(maxCap, x);
            }
        }

        // Model:
        // Each side part with height > H needs support interval of length (height-H)
        // on top of some center part(s).
        // Each side part with height < H contributes available top interval of length (H-height)
        // on its own center part side.
        //
        // Since the table is arbitrarily wide, only total available support lengths matter,
        // and support can be chained. Feasibility reduces to whether every needed interval
        // can be packed into available intervals.
        //
        // Necessary and sufficient:
        // 1) total capacity >= total need
        // 2) the largest single need fits into some connected support obtainable from others.
        //    Because supports come from individual side deficits, this is equivalent to
        //    largest need <= total capacity excluding its own impossible self-support issue,
        //    and in interval-packing form reduces to maxNeed <= sumCap.
        // Also trivially if sumNeed == 0 it's possible.

        boolean ok = sumNeed <= sumCap;

        System.out.println(ok ? "Yes" : "No");
    }
}

