#include <bits/stdc++.h>
using namespace std;
int main(){
    int N, H;
    cin >> N >> H;
    map<int,int> indeg, outdeg;
    map<pair<int,int>, int> edges;
    for(int i=0;i<N;i++){
        int a,b; cin>>a>>b;
        // edge from (H-b) to a
        outdeg[H-b]++; indeg[a]++;
        edges[{H-b,a}]++;
    }
    // Check Eulerian path in directed graph
    set<int> nodes;
    for(auto&p:indeg) nodes.insert(p.first);
    for(auto&p:outdeg) nodes.insert(p.first);
    int start=0,end=0;
    for(auto v:nodes){
        int id=indeg[v], od=outdeg[v];
        if(od-id==1) start++;
        else if(id-od==1) end++;
        else if(id!=od){cout<<"NO\n";return 0;}
    }
    if(!((start==0&&end==0)||(start==1&&end==1))){cout<<"NO\n";return 0;}
    // Check connectivity (ignoring direction) among nodes with edges
    // Use union-find
    map<int,int> par;
    function<int(int)> find=[&](int x)->int{
        if(!par.count(x))par[x]=x;
        return par[x]==x?x:par[x]=find(par[x]);
    };
    auto unite=[&](int x,int y){
        x=find(x);y=find(y);
        if(x!=y)par[x]=y;
    };
    for(auto&e:edges) unite(e.first.first,e.first.second);
    set<int> roots;
    for(auto v:nodes) roots.insert(find(v));
    cout<<(roots.size()<=1?"YES":"NO")<<"\n";
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long H;
    cin >> N >> H;

    vector<long long> A(N), B(N);
    for (int i = 0; i < N; i++) cin >> A[i] >> B[i];

    // View each piece as:
    // left leg height A_i, center height H, right leg height B_i.
    //
    // Since every center bottom must touch the table front side, all centers lie on the base line.
    // A side part can either also touch the base line, or be supported by the top of another side part.
    //
    // Because pieces are not rotated/flipped and supports are horizontal tops of width 1,
    // the only thing that matters is matching heights:
    // - A left part of height x can be supported by a right part of height x.
    // - A right part of height x can be supported by a left part of height x.
    // Parts with height <= H can always touch the table directly.
    // Parts with height > H must be supported at level (height - H), equivalently they need
    // a counterpart of the same excess height on the opposite side.
    //
    // Thus for each d > 0:
    // count of left parts with A_i = H + d must not exceed count of right parts with B_i = d
    //? Actually support top height must equal bottom height of overhanging part.
    // If a side part has total height X > H, then its bottom must be at height X-H above table.
    // So it needs a supporting opposite-side part whose top is exactly X-H.
    // Therefore:
    //   left X>H needs right (X-H)
    //   right X>H needs left (X-H)
    //
    // This creates recursive dependencies. Let fL[h], fR[h] be counts of left/right parts of height h.
    // A part of height h can support a taller opposite part of height h+H.
    // Parts of height <= H may stand on table.
    // Greedy from small to large:
    // available left supports at height h = count of left parts of height h
    // plus left parts of height h that stand somehow? Actually every part exists regardless;
    // the condition is whether its own bottom can be placed. If h<=H, it is placeable.
    // If h>H, to place left h we need one right support of height h-H that is itself placeable.
    //
    // So define placeable counts recursively:
    // placeableLeft[h] = countLeft[h] if h<=H, else min(countLeft[h], placeableRight[h-H])
    // similarly for right.
    // But one support can support multiple pieces along width due huge table? No, width-1 top can support exactly one width-1 part.
    // Thus matching is one-to-one, consuming supports.
    //
    // Let dp over heights:
    // base placeable counts for <=H are all their counts.
    // For h>H, number of placeable left parts at h equals min(countLeft[h], remaining placeable right at h-H]),
    // and those consumed supports reduce availability of right at h-H for supporting higher pieces.
    //
    // This is exactly a chain per residue modulo H.
    // For each residue r in [1..H] conceptually, heights r, r+H, r+2H...
    // counts alternate consumption between sides.
    //
    // Since H can be huge, only finitely many heights appear. Compress by value and memo recursively.
    //
    // Let need/place relation:
    // left at x>H needs one placeable right at x-H.
    // right at x>H needs one placeable left at x-H.
    //
    // For each chain starting from base heights <=H, process upward by steps H.
    // Maintain available placeable counts at current height for each side after reserving some to support opposite higher parts.
    //
    // If at height t we have L[t], R[t].
    // Higher demands are from R[t+H] needing L[t], and L[t+H] needing R[t].
    // To maximize placeability, all placeable supports should be used for higher opposite parts if possible,
    // since supports themselves are already placeable. We can process upward:
    // placeL[t]=L[t] for t<=H or determined earlier
    // placeR[t]=R[t]
    // Then at t+H:
    // placeL[t+H]=min(L[t+H], placeR[t])
    // placeR[t+H]=min(R[t+H], placeL[t])
    // This does not consume supports multiple times incorrectly because supports at height t can be used
    // both for supporting left at t+H and right at t+H? No, a single part can support at most one part.
    // So capacities must be shared:
    // x = number of left at t+H placed using right[t]
    // y = number of right at t+H placed using left[t]
    // independent, since they use opposite supports. No conflict.
    // Thus formula is correct.
    //
    // Finally all pieces are placeable iff for every i, left A_i and right B_i are placeable in full count at their heights.
    // That means for every height h, placeL[h] == countLeft[h], placeR[h] == countRight[h].

    unordered_map<long long, long long> cntL, cntR;
    cntL.reserve(N * 2 + 10);
    cntR.reserve(N * 2 + 10);
    vector<long long> hs;
    hs.reserve(2 * N + 5);

    for (int i = 0; i < N; i++) {
        cntL[A[i]]++;
        cntR[B[i]]++;
        hs.push_back(A[i]);
        hs.push_back(B[i]);
    }

    sort(hs.begin(), hs.end());
    hs.erase(unique(hs.begin(), hs.end()), hs.end());

    unordered_map<long long, long long> placeL, placeR;
    placeL.reserve(hs.size() * 2 + 10);
    placeR.reserve(hs.size() * 2 + 10);

    for (long long h : hs) {
        long long cL = cntL.count(h) ? cntL[h] : 0;
        long long cR = cntR.count(h) ? cntR[h] : 0;
        if (h <= H) {
            placeL[h] = cL;
            placeR[h] = cR;
        } else {
            long long pr = placeR.count(h - H) ? placeR[h - H] : 0;
            long long pl = placeL.count(h - H) ? placeL[h - H] : 0;
            placeL[h] = min(cL, pr);
            placeR[h] = min(cR, pl);
        }
    }

    bool ok = true;
    for (long long h : hs) {
        if (placeL[h] != cntL[h] || placeR[h] != cntR[h]) {
            ok = false;
            break;
        }
    }

    cout << (ok ? "Yes\n" : "No\n");
    return 0;
}
